lib_src = '''
def cells(grid, color):
    """All (row, col) positions holding the given color."""
    return [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == color]

def components(grid, color, conn8=True):
    """Connected components (as cell lists) of the given color, 8-connected by default."""
    remaining = set(cells(grid, color)); out = []
    while remaining:
        seed = remaining.pop(); stack = [seed]; comp = [seed]
        while stack:
            i, j = stack.pop()
            for di in (-1, 0, 1):
                for dj in (-1, 0, 1):
                    if (di or dj) and (not conn8 or abs(di)+abs(dj) < 2 or conn8):
                        p = (i+di, j+dj)
                        if p in remaining:
                            remaining.discard(p); stack.append(p); comp.append(p)
        out.append(comp)
    return out

def centers(grid, color=2):
    """Centroid (rounded) of each connected component of the color (e.g. hollow diamond centers)."""
    return sorted((round(sum(i for i, _ in c)/len(c)), round(sum(j for _, j in c)/len(c)))
                  for c in components(grid, color))

def connect_aligned(grid, centers, color=1):
    """Draw color along rows/columns between consecutive centers sharing a row or column."""
    out = [row[:] for row in grid]
    by_row, by_col = {}, {}
    for i, j in centers:
        by_row.setdefault(i, []).append(j)
        by_col.setdefault(j, []).append(i)
    for i, js in by_row.items():
        for a, b in zip(sorted(js), sorted(js)[1:]):
            for j in range(a+1, b):
                if out[i][j] == 0: out[i][j] = color
    for j, is_ in by_col.items():
        for a, b in zip(sorted(is_), sorted(is_)[1:]):
            for i in range(a+1, b):
                if out[i][j] == 0: out[i][j] = color
    return out
'''
